import semarang from "@/content/terrain/semarang-hazard-webgis.json";
import cidata from "@/content/terrain/cidata-mining-platform.json";
import pertagas from "@/content/terrain/pertagas-security-dashboard.json";
import kristalin from "@/content/terrain/kristalin-corporate-site.json";
import thesis from "@/content/terrain/b2b-exporter-ecommerce.json";

/** Real contour lines around a project's location, generated by `npm run terrain`. */
export type Terrain = {
  lat: number;
  lon: number;
  min: number;
  max: number;
  interval: number;
  paths: { d: string; major: boolean }[];
};

const terrain: Record<string, Terrain> = {
  "semarang-hazard-webgis": semarang,
  "cidata-mining-platform": cidata,
  "pertagas-security-dashboard": pertagas,
  "kristalin-corporate-site": kristalin,
  "b2b-exporter-ecommerce": thesis,
};

export const getTerrain = (slug: string): Terrain | undefined => terrain[slug];

export const formatCoords = (lat: number, lon: number) =>
  `${Math.abs(lat).toFixed(2)}°${lat < 0 ? "S" : "N"} ${Math.abs(lon).toFixed(2)}°${lon < 0 ? "W" : "E"}`;
